const total = $state.context.REQUEST.DATA.po.receivedQuantity.value;
const wop = $state.context.LOCAL.wop;
const bom = wop.workOrderProcessBoms.edges.map(v=>v.node);
const consumption = {};
let success = true
const inv = $.inventory.edges.reduce((a,c)=>{
  const k = c.node.product.id;
  if(!a[k]) {
    a[k]=[]
  }
  a[k].push(c.node);
  return a;
},{});


for(let i=0; i<bom.length; i++) {
  const b = bom[i];
  const prod = b.componentProduct.id;
  consumption[prod] = [];
  const compInv = inv[prod];
  let req = b.standardUsage * total;
  for(let ii=0; ii<compInv.length; ii++){
    const comp = compInv[ii];
    if (req>0){
      const cons = Math.min(req, comp.quantity.value);
      const qty = comp.quantity.value - cons;
      consumption[prod].push({
        id: comp.id,
        usage: cons,
        qty
      });
      req-=cons;
    } else break;
  }
    if(req > 0) {
      success=false;
      break;
    }
  }

const r = [];
Object.entries(consumption).forEach(([productId, v]) => { r.push(...v.map(vv => ({ ...vv, productId: productId }))) });
return {
  success,
  consumption: r
}

