			"_in": [$.REQUEST.DATA.distributions.edges.node.workOrderProcessId]
		}
	},
	"wherePoType": {
		"outsideProcessing": { "_eq": true },
		"active": { "_eq": true },
		"usable": { "_eq": true }
	},
	"firstPoType": 1,
	"wherePoStatus": {
		"default": { "_eq": true }
	},
	"firstPoStatus": 1,
	"wherePoLineStatus": {
		"active": { "_eq": true },
		"usable": { "_eq": true },
		"partial": { "_eq": false }
	},
	"firstPoLineStatus": 1
}

data.query:
query ($wherePoLineStatus: PurchaseOrderLineStatusWhereInput, $firstPoLineStatus: Int, $wherePoStatus: PurchaseOrderStatusWhereInput, $firstPoStatus: Int, $wop: WorkOrderProcessWhereInput, $wherePoType: PurchaseOrderTypeWhereInput, $firstPoType: Int) {
  workOrderProcess(where: $wop) {
    edges {
      node {
        id
        quantity
        order
        processId
        workOrder {
          id
          facilityId
          productId
          productStrategy {
            strategyProcesses {
              edges {
                node {
                  id
                  order
                  productionType {
                    outside
                  }
                }
              }
            }
            inventoryUnitId
          }
          workOrderProcesses {
            edges {
              node {
                id
                order
                productionType {
                  outside
                }
                workOrderProcessBoms {
                  edges {
                    node {
                      id
                      order
                      rate
                      standardUsage
                      active
                    }
                  }
                }
              }
            }
          }
        }
        workOrderProcessStatusId
        workcenterId
        workcenter {
          facilityId
          supplierId
        }
        workOrderProcessBoms(where: {active: {_eq: true}, bomTypeId: {_eq: "Product"}}) {
          edges {
            node {
              id
              standardUsage
              bomTypeId
              componentProduct {
                id
                code
                strategies(first: 1, where: {active: {_eq: true}}) {
                  edges {
                    node {
                      inventoryUnitId
                    }
                  }
                }
              }
            }
          }
        }
        workOrderProcessDistributions {
          edges {
            node {
              id
              distributionGroupId
            }
          }
        }
      }
    }
  }
  purchaseOrderType(where: $wherePoType, first: $firstPoType) {
    edges {
      node {
        id
        name
      }
    }
  }
  purchaseOrderStatus(where: $wherePoStatus, first: $firstPoStatus) {
    edges {
      node {
        id
        name
        active
        cancelled
        closed
        default
        extDefault
        hold
        system
        usable
        externalId
      }
    }
  }
  purchaseOrderLineStatus(where: $wherePoLineStatus, first: $firstPoLineStatus) {
    edges {
      node {
        id
        name
        active
        cancelled
        closed
        partial
        received
        system
        usable
        externalId
      }
    }
  }
}
